def longestDiverseString(a, b, c):
    def get_max_char(a, b, c):
        if a >= b and a >= c:
            return 'a'
        if b >= a and b >= c:
            return 'b'
        return 'c'

    def can_add_char(s, char, count):
        if len(s) < 2:
            return True
        return s[-1] != char or s[-2] != char

    s = ""
    while a > 0 or b > 0 or c > 0:
        max_char = get_max_char(a, b, c)
        if max_char == 'a' and a > 0 and can_add_char(s, 'a', a):
            s += 'a'
            a -= 1
        elif max_char == 'b' and b > 0 and can_add_char(s, 'b', b):
            s += 'b'
            b -= 1
        elif max_char == 'c' and c > 0 and can_add_char(s, 'c', c):
            s += 'c'
            c -= 1
        else:
            break
    return s

